#!/usr/bin/env node
/*
 * CHANGELOG.md generator (`npm run changelog`, `npm run changelog:check`).
 *
 * The top of CHANGELOG.md is generated by git-cliff (cliff.toml) from the
 * Conventional Commits on the current branch (main at release time). Commits up
 * to and including 53620ef (#33) predate Conventional Commits and are left out.
 * Their changes are the hand-written section that starts at HISTORY_HEADING;
 * this script copies that section through verbatim, so it is never regenerated,
 * and refuses to run if its text no longer matches HISTORY_SHA256.
 *
 * --check exits 1 when CHANGELOG.md differs from what would be generated.
 */
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const file = join(root, "CHANGELOG.md");
// The last commit on main before Conventional Commits (#33).
const LAST_UNCONVENTIONAL = "53620ef57b2a4728bcff6596e0d59b76c81ca95b";
const HISTORY_HEADING = "## Before Conventional Commits (hand-written, Nov 20–21, 2026)";
// SHA-256 of that section, heading to end of file.
const HISTORY_SHA256 = "036cf4f486c69615047461b5a0eb957162980545dba776f004e27c4836945d0c";

const current = readFileSync(file, "utf8");
const at = current.indexOf(`\n${HISTORY_HEADING}\n`);
if (at === -1) {
  console.error(`CHANGELOG.md: missing the "${HISTORY_HEADING}" section to preserve.`);
  process.exit(1);
}
const history = current.slice(at + 1);
if (createHash("sha256").update(history).digest("hex") !== HISTORY_SHA256) {
  console.error(`CHANGELOG.md: the "${HISTORY_HEADING}" section was edited. Restore it from git.`);
  process.exit(1);
}

const generated = execFileSync(
  join(root, "node_modules", ".bin", process.platform === "win32" ? "git-cliff.cmd" : "git-cliff"),
  ["--config", join(root, "cliff.toml"), `${LAST_UNCONVENTIONAL}..HEAD`],
  { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "inherit"], shell: process.platform === "win32" },
).trimEnd();

// With no conventional commits yet, git-cliff prints only the header.
const unreleased = /^## /m.test(generated) ? "" : "\n\n## [Unreleased]";
const next = `${generated}${unreleased}\n\n${history}`;

if (process.argv.includes("--check")) {
  if (next !== current) {
    console.error("CHANGELOG.md is out of date. Run `npm run changelog`.");
    process.exit(1);
  }
  console.log("CHANGELOG.md is up to date.");
} else {
  writeFileSync(file, next);
  console.log("CHANGELOG.md written.");
}
